package executors

// Fixture + protocol tests for the Cursor port. The byte fixtures in
// cursorFixtures were generated by running the ORIGINAL JS encoders
// (open-sse/utils/cursorProtobuf.js + cursorChecksum.js, with the
// clock stubbed and uuid stubbed) — so byte equality here means the
// Go wire format matches the JS wire format exactly. The end-to-end
// tests run against a local HTTP/2 test server only; no real Cursor
// network calls.

import (
	"context"
	"crypto/tls"
	"encoding/hex"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
	"time"

	"golang.org/x/net/http2"
)

func cursorFixtureBytes(t *testing.T, key string) []byte {
	t.Helper()
	raw, ok := cursorFixtures[key]
	if !ok {
		t.Fatalf("missing fixture %q", key)
	}
	b, err := hex.DecodeString(raw)
	if err != nil {
		t.Fatalf("fixture %q is not hex: %v", key, err)
	}
	return b
}

func assertFixtureBytes(t *testing.T, key string, got []byte) {
	t.Helper()
	want := cursorFixtureBytes(t, key)
	if hex.EncodeToString(got) != hex.EncodeToString(want) {
		t.Errorf("%s:\n got %x\nwant %x", key, got, want)
	}
}

// ---------- protobuf encoder fixtures (JS-generated) ----------

func TestCursorProtobufEncoderFixtures(t *testing.T) {
	assertFixtureBytes(t, "encodeModel", encodeModel("gpt-5.2"))
	assertFixtureBytes(t, "encodeMessageUser",
		encodeMessage("Hello", 1, "11111111-2222-3333-4444-555555555555", false, false, nil, ""))
	assertFixtureBytes(t, "encodeMessageAgent",
		encodeMessage("Hi there", 2, "aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee", true, true, nil, ""))
	assertFixtureBytes(t, "encodeToolResult", EncodeToolResult(CursorToolResult{
		ToolCallID:    "call_123\nmc_model456",
		ToolName:      "Write",
		RawArgs:       `{"path":"x"}`,
		ResultContent: "ok done",
		ToolIndex:     2,
	}))
	assertFixtureBytes(t, "buildToolResultRequest", BuildToolResultRequest(CursorToolResult{
		ToolCallID:    "call_9",
		ToolName:      "mcp_custom_Read",
		ResultContent: "file body",
	}))
	if got := encodeInstruction(""); len(got) != 0 {
		t.Errorf("encodeInstruction(\"\") = %x, want empty", got)
	}
	assertFixtureBytes(t, "encodeCursorSetting", encodeCursorSetting())
	assertFixtureBytes(t, "encodeMcpTool", encodeMcpTool(CursorToolDef{
		Name:        "Read",
		Description: "read a file",
		InputSchema: map[string]any{"type": "object"},
	}))
	// Note: the encodeMcpTools fixture was generated with the schema
	// keys in alphabetical order — Go maps marshal JSON with sorted
	// keys, while JS preserves the caller's insertion order; the
	// schema is a JSON string field that Cursor parses, so key order
	// inside it is not wire-significant.
	assertFixtureBytes(t, "encodeMcpTools", EncodeMcpTools([]CursorToolDef{{
		Name:        "Read",
		Description: "read",
		InputSchema: map[string]any{"type": "object", "properties": map[string]any{}},
	}}))
}

func TestCursorAgentValueFixtures(t *testing.T) {
	assertFixtureBytes(t, "agentValueString", EncodeAgentValue("hello"))
	assertFixtureBytes(t, "agentValueNumber", EncodeAgentValue(3.5))
	assertFixtureBytes(t, "agentValueBool", EncodeAgentValue(true))
	assertFixtureBytes(t, "agentValueNull", EncodeAgentValue(nil))
	assertFixtureBytes(t, "agentValueStruct", EncodeAgentValue(map[string]any{"a": float64(1), "b": "x"}))
	assertFixtureBytes(t, "agentValueList", EncodeAgentValue([]any{float64(1), "y"}))

	// Round trips.
	if got := DecodeAgentValue(EncodeAgentValue(map[string]any{"a": float64(1), "b": "x"})); got == nil {
		t.Error("struct round trip returned nil")
	} else if m, ok := got.(map[string]any); !ok || m["a"] != float64(1) || m["b"] != "x" {
		t.Errorf("struct round trip = %#v", got)
	}
	if got := DecodeAgentValue(EncodeAgentValue("hello")); got != "hello" {
		t.Errorf("string round trip = %#v", got)
	}
}

