func extractFixture(t *testing.T, key string) CursorExtract {
	t.Helper()
	_, payload, _, ok := ParseConnectRPCFrame(cursorFixtureBytes(t, key))
	if !ok {
		t.Fatalf("ParseConnectRPCFrame(%s) failed", key)
	}
	return ExtractTextFromResponse(payload)
}

func TestCursorResponseFixtures(t *testing.T) {
	text := extractFixture(t, "frameText")
	if !text.HasText || text.Text != "Hello from Cursor" {
		t.Errorf("frameText = %+v", text)
	}
	thinking := extractFixture(t, "frameThinking")
	if !thinking.HasThinking || thinking.Thinking != "deep thought" {
		t.Errorf("frameThinking = %+v", thinking)
	}
	tool := extractFixture(t, "frameToolCall")
	if tool.ToolCall == nil {
		t.Fatalf("frameToolCall: no tool call extracted")
	}
	tc := tool.ToolCall
	if tc.ID != "call_77" || tc.FunctionName != "Read" || tc.FunctionArgs != `{"path":"/a"}` || !tc.IsLast || tc.Type != "function" {
		t.Errorf("frameToolCall = %+v (JS ground truth: id=call_77 name=Read args={\"path\":\"/a\"} isLast=true)", tc)
	}
	gz := extractFixture(t, "frameTextGzip")
	if !gz.HasText || gz.Text != "Hello from Cursor" {
		t.Errorf("frameTextGzip = %+v", gz)
	}
}

// ---------- checksum / session fixtures (JS-generated) ----------

func TestCursorChecksumFixtures(t *testing.T) {
	if got := GenerateHashed64Hex("token123"); got != cursorFixtures["hashed"] {
		t.Errorf("GenerateHashed64Hex = %s, want %s", got, cursorFixtures["hashed"])
	}
	if got := GenerateHashed64Hex("token123", "machineId"); got != cursorFixtures["hashedSalt"] {
		t.Errorf("GenerateHashed64Hex(salt) = %s, want %s", got, cursorFixtures["hashedSalt"])
	}
	if got := GenerateSessionID("token123"); got != cursorFixtures["sessionId"] {
		t.Errorf("GenerateSessionID = %s, want %s", got, cursorFixtures["sessionId"])
	}
	if got := generateCursorChecksumAt("machine-abc-123", 1760000000000); got != cursorFixtures["checksum"] {
		t.Errorf("checksum = %s, want %s", got, cursorFixtures["checksum"])
	}
	headers := BuildCursorHeaders("user::tok123", "machine-abc-123", true)
	if headers["authorization"] != "Bearer tok123" {
		t.Errorf("authorization = %q", headers["authorization"])
	}
	if headers["x-cursor-checksum"] == "" || headers["x-session-id"] == "" || headers["x-ghost-mode"] != "true" {
		t.Errorf("headers missing checksum/session/ghost: %v", headers)
	}
	if headers["x-cursor-client-version"] != "3.12.17" {
		t.Errorf("x-cursor-client-version = %q", headers["x-cursor-client-version"])
	}
}

