func TestCursorUsableModelsFixture(t *testing.T) {
	payload := cursorFixtureBytes(t, "usableModels")
	models := ParseCursorUsableModels(payload)
	if len(models) != 2 || models[0].ID != "composer-1" || models[1].ID != "gpt-5.2" {
		t.Fatalf("ParseCursorUsableModels = %+v", models)
	}
	merged := MergeCursorModelFlags(models, payload)
	var composer *CursorCatalogModel
	for i := range merged {
		if merged[i].ID == "composer-1" {
			composer = &merged[i]
		}
	}
	if composer == nil || !composer.DefaultOn || !composer.SupportsAgent {
		t.Fatalf("merged composer-1 = %+v", composer)
	}
	selection, ok := ResolveAutoModelSelection(merged)
	if !ok || selection != "composer-1" {
		t.Errorf("ResolveAutoModelSelection = %q, %v; want composer-1", selection, ok)
	}
}

