// ---------- legacy transforms over fixture frames ----------

func readBodyString(t *testing.T, resp *http.Response) string {
	t.Helper()
	defer resp.Body.Close()
	b, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatalf("read body: %v", err)
	}
	return string(b)
}

func TestCursorLegacyTransforms(t *testing.T) {
	body := map[string]any{"model": "gpt-5.2", "messages": []any{}}
	resp := transformProtobufToJSON(cursorFixtureBytes(t, "frameText"), "gpt-5.2", body)
	if resp.StatusCode != 200 {
		t.Fatalf("JSON transform status = %d", resp.StatusCode)
	}
	var completion map[string]any
	if err := json.Unmarshal([]byte(readBodyString(t, resp)), &completion); err != nil {
		t.Fatalf("completion JSON: %v", err)
	}
	choices := completion["choices"].([]any)
	message := choices[0].(map[string]any)["message"].(map[string]any)
	if message["content"] != "Hello from Cursor" {
		t.Errorf("JSON content = %#v", message["content"])
	}
	usage := completion["usage"].(map[string]any)
	if usage["estimated"] != true || usage["prompt_tokens"].(float64) < 2000 {
		t.Errorf("usage = %#v (want estimated + 2000 buffer)", usage)
	}

	sse := readBodyString(t, transformProtobufToSSE(cursorFixtureBytes(t, "frameText"), "gpt-5.2", body))
	if !strings.Contains(sse, "Hello from Cursor") || !strings.Contains(sse, "[DONE]") || !strings.Contains(sse, `"finish_reason":"stop"`) {
		t.Errorf("SSE transform missing content/finish/DONE:\n%s", sse)
	}

	toolSSE := readBodyString(t, transformProtobufToSSE(cursorFixtureBytes(t, "frameToolCall"), "gpt-5.2", body))
	if !strings.Contains(toolSSE, `"name":"Read"`) || !strings.Contains(toolSSE, `"finish_reason":"tool_calls"`) {
		t.Errorf("SSE tool transform wrong:\n%s", toolSSE)
	}
}

// ---------- end-to-end against a local HTTP/2 server ----------

func cursorTestProvider(endpoint string) *ProviderInfo {
	return &ProviderInfo{
		ID: "cursor",
		Raw: map[string]any{
			"oauth": map[string]any{"agentEndpoint": endpoint},
		},
	}
}

func cursorTestCred() Credential {
	return Credential{
		AccessToken: "tok123",
		Specific:    map[string]any{"machineId": "machine-test-1"},
	}
}

func swapCursorTransport(t *testing.T) {
	t.Helper()
	restore := cursorH2Transport
	cursorH2Transport = &http2.Transport{TLSClientConfig: &tls.Config{InsecureSkipVerify: true}} //nolint:gosec // local test server
	t.Cleanup(func() { cursorH2Transport = restore })
}

// readOneFrame reads a single Connect frame from a request body.
func readOneFrame(r io.Reader) (byte, []byte, error) {
	header := make([]byte, 5)
	if _, err := io.ReadFull(r, header); err != nil {
		return 0, nil, err
	}
	length := int(header[1])<<24 | int(header[2])<<16 | int(header[3])<<8 | int(header[4])
	payload := make([]byte, length)
	if _, err := io.ReadFull(r, payload); err != nil {
		return 0, nil, err
	}
	return header[0], payload, nil
}

func writeFrame(w io.Writer, payload []byte) {
	frame := WrapConnectRPCFrame(payload, false)
	_, _ = w.Write(frame)
}

func TestCursorAgentEndToEnd(t *testing.T) {
	swapCursorTransport(t)
	ackReceived := make(chan []byte, 1)
	runReceived := make(chan []byte, 1)

	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != agentRunPath {
			http.NotFound(w, r)
			return
		}
		// First client frame: the Run request.
		_, runPayload, err := readOneFrame(r.Body)
		if err != nil {
			return
		}
		runReceived <- runPayload
		flusher, _ := w.(http.Flusher)
		w.Header().Set("Content-Type", "application/connect+proto")
		w.WriteHeader(http.StatusOK)
		if flusher != nil {
			flusher.Flush()
		}
		// Exec request_context (field 2 = ExecServerMessage,
		// {1: id, 15: exec id, 10: request_context}) — the client
		// must ack on the same request stream before we send text.
		execReq := pbConcat(pbVar(1, 7), pbStr(15, "exec-1"), pbLen(10, []byte{0x08, 0x01}))
		writeFrame(w, pbLen(2, execReq))
		if flusher != nil {
			flusher.Flush()
		}
		_, ackPayload, err := readOneFrame(r.Body)
		if err != nil {
			return
		}
		ackReceived <- ackPayload
		// Text deltas + turn end (field 1 = interaction_update).
		writeFrame(w, pbLen(1, pbLen(1, pbStr(1, "Hello "))))
		writeFrame(w, pbLen(1, pbLen(1, pbStr(1, "agent"))))
		writeFrame(w, pbLen(1, pbLen(14, []byte{})))
		if flusher != nil {
			flusher.Flush()
		}
	})
	server := httptest.NewUnstartedServer(handler)
	server.EnableHTTP2 = true
	server.StartTLS()
	defer server.Close()

	executor := NewCursorExecutor()
	body := []byte(`{"model":"composer-1","messages":[{"role":"user","content":"hi"}],"stream":true}`)
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	result, err := executor.Execute(ctx, cursorTestProvider(server.URL), cursorTestCred(), body)
	if err != nil {
		t.Fatalf("Execute: %v", err)
	}
	if result.Response.StatusCode != 200 {
		t.Fatalf("status = %d", result.Response.StatusCode)
	}
	sse := readBodyString(t, result.Response)
	if !strings.Contains(sse, "Hello ") || !strings.Contains(sse, "agent") || !strings.Contains(sse, "[DONE]") {
		t.Errorf("agent SSE missing deltas/DONE:\n%s", sse)
	}
	if !strings.Contains(sse, `"finish_reason":"stop"`) {
		t.Errorf("agent SSE missing finish chunk:\n%s", sse)
	}

	select {
	case ack := <-ackReceived:
		msg := pbDecodeMessage(ack)
		if !msg.has(2) {
			t.Errorf("ack frame has no exec client message (field 2): %x", ack)
			break
		}
		execClient := pbDecodeMessage(msg.firstBytes(2))
		if !execClient.has(10) {
			t.Errorf("ack exec message has no request_context result (field 10): %x", ack)
		}
	default:
		t.Error("server never received the request_context ack")
	}
	select {
	case run := <-runReceived:
		msg := pbDecodeMessage(run)
		if !msg.has(1) {
			t.Errorf("Run frame has no RunRequest (field 1): %x", run)
		}
	default:
		t.Error("server never received the Run frame")
	}
}

func TestCursorAgentNonStreaming(t *testing.T) {
	swapCursorTransport(t)
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _, err := readOneFrame(r.Body)
		if err != nil {
			return
		}
		flusher, _ := w.(http.Flusher)
		w.Header().Set("Content-Type", "application/connect+proto")
		w.WriteHeader(http.StatusOK)
		writeFrame(w, pbLen(1, pbLen(1, pbStr(1, "Hello agent"))))
		writeFrame(w, pbLen(1, pbLen(14, []byte{})))
		if flusher != nil {
			flusher.Flush()
		}
	})
	server := httptest.NewUnstartedServer(handler)
	server.EnableHTTP2 = true
	server.StartTLS()
	defer server.Close()

	executor := NewCursorExecutor()
	body := []byte(`{"model":"composer-1","messages":[{"role":"user","content":"hi"}],"stream":false}`)
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	result, err := executor.Execute(ctx, cursorTestProvider(server.URL), cursorTestCred(), body)
	if err != nil {
		t.Fatalf("Execute: %v", err)
	}
	text := readBodyString(t, result.Response)
	var completion map[string]any
	if err := json.Unmarshal([]byte(text), &completion); err != nil {
		t.Fatalf("completion JSON: %v (%s)", err, text)
	}
	choices := completion["choices"].([]any)
	message := choices[0].(map[string]any)["message"].(map[string]any)
	if message["content"] != "Hello agent" {
		t.Errorf("content = %#v", message["content"])
	}
}

func TestCursorLegacyEndToEnd(t *testing.T) {
	swapCursorTransport(t)
	var sawPath string
	var sawBody []byte
	var mu sync.Mutex
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		sawPath = r.URL.Path
		sawBody, _ = io.ReadAll(r.Body)
		mu.Unlock()
		w.Header().Set("Content-Type", "application/connect+proto")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write(cursorFixtureBytes(t, "frameText"))
	})
	server := httptest.NewUnstartedServer(handler)
	server.EnableHTTP2 = true
	server.StartTLS()
	defer server.Close()

	provider := &ProviderInfo{
		ID:      "cursor",
		BaseURL: server.URL,
		Raw: map[string]any{
			"transport": map[string]any{"chatPath": cursorDefaultChatPath},
		},
	}
	executor := NewCursorExecutor()
	// An image part makes the request NOT agent-capable → legacy path.
	body := []byte(`{"model":"gpt-5.2","stream":false,"messages":[{"role":"user","content":[{"type":"text","text":"describe"},{"type":"image_url","image_url":{"url":"data:image/png;base64,AA=="}}]}]}`)
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	result, err := executor.Execute(ctx, provider, cursorTestCred(), body)
	if err != nil {
		t.Fatalf("Execute: %v", err)
	}
	text := readBodyString(t, result.Response)
	var completion map[string]any
	if err := json.Unmarshal([]byte(text), &completion); err != nil {
		t.Fatalf("completion JSON: %v (%s)", err, text)
	}
	choices := completion["choices"].([]any)
	message := choices[0].(map[string]any)["message"].(map[string]any)
	if message["content"] != "Hello from Cursor" {
		t.Errorf("content = %#v", message["content"])
	}
	mu.Lock()
	defer mu.Unlock()
	if sawPath != cursorDefaultChatPath {
		t.Errorf("path = %q", sawPath)
	}
	if len(sawBody) < 5 {
		t.Errorf("request body too small: %d bytes", len(sawBody))
	}
}

func TestCursorLegacyUpstreamError(t *testing.T) {
	swapCursorTransport(t)
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = io.ReadAll(r.Body)
		w.WriteHeader(http.StatusTooManyRequests)
		_, _ = w.Write([]byte("slow down"))
	})
	server := httptest.NewUnstartedServer(handler)
	server.EnableHTTP2 = true
	server.StartTLS()
	defer server.Close()

	provider := &ProviderInfo{ID: "cursor", BaseURL: server.URL}
	executor := NewCursorExecutor()
	body := []byte(`{"model":"gpt-5.2","stream":false,"messages":[{"role":"user","content":[{"type":"image_url","image_url":{"url":"data:image/png;base64,AA=="}}]}]}`)
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	result, err := executor.Execute(ctx, provider, cursorTestCred(), body)
	if err != nil {
		t.Fatalf("Execute: %v", err)
	}
	if result.Response.StatusCode != 429 {
		t.Fatalf("status = %d", result.Response.StatusCode)
	}
	if text := readBodyString(t, result.Response); !strings.Contains(text, "[429]: slow down") {
		t.Errorf("error body = %s", text)
	}
}

func TestCursorMachineIDRequired(t *testing.T) {
	executor := NewCursorExecutor()
	noMachine := Credential{AccessToken: "tok123"}

	// Legacy path: like the JS, buildHeaders is called outside the
	// try block, so the error propagates out of Execute.
	legacyBody := []byte(`{"model":"gpt-5.2","messages":[{"role":"user","content":[{"type":"image_url","image_url":{"url":"data:image/png;base64,AA=="}}]}]}`)
	_, err := executor.Execute(context.Background(), cursorTestProvider("https://127.0.0.1:1"), noMachine, legacyBody)
	if err == nil || !strings.Contains(err.Error(), "Machine ID is required for Cursor API") {
		t.Errorf("legacy machine-id error = %v", err)
	}

	// Agent path: the JS wraps executeAgent errors into a 500
	// connection_error result.
	agentBody := []byte(`{"model":"composer-1","messages":[{"role":"user","content":"hi"}]}`)
	result, err := executor.Execute(context.Background(), cursorTestProvider("https://127.0.0.1:1"), noMachine, agentBody)
	if err != nil {
		t.Fatalf("agent Execute: %v", err)
	}
	if result.Response.StatusCode != 500 {
		t.Fatalf("agent status = %d", result.Response.StatusCode)
	}
	if text := readBodyString(t, result.Response); !strings.Contains(text, "Machine ID is required") || !strings.Contains(text, "connection_error") {
		t.Errorf("agent error body = %s", text)
	}
}

